"""Curated seed list of animal taxa named in chapters VI–X of *On the Origin of Species*.

Each entry gives the slug, the scientific name used to query the authorities, the rank we
expect, the regular expressions (case-insensitive, matched on the chapter text and on claim
text) that recognise the name as Darwin wrote it, and notes on how an archaic or vernacular
name was resolved. ``skip_lines`` lists book lines where the regex would hit a false positive
(e.g. "hen" in "hen ostriches").
"""

TEXT_START, TEXT_END = 5290, 10411  # CHAPTER VI. ... end of chapter X (1-indexed lines of pg1228.txt)
CHAPTERS = ("VI", "VII", "VIII", "IX", "X")

W = r"(?<![\w-])"  # word start that also blocks hyphen-joined prefixes
E = r"(?![\w-])"   # word end that blocks hyphen-joined suffixes


def T(slug, query, rank, patterns, notes="", marine=False, fossil=False, skip_lines=(),
      gbif_key=None, wikidata=None, vernacular=None, ncbi_query=None):
    return dict(slug=slug, query=query, rank=rank, patterns=patterns, notes=notes,
                marine=marine, fossil=fossil, skip_lines=list(skip_lines), gbif_key=gbif_key,
                wikidata=wikidata, vernacular=vernacular or [], ncbi_query=ncbi_query)


